- name: "Enforce rule"
  run: |
    #!/usr/bin/env bash
    set -euo pipefail
    found=0
    while IFS= read -r f; do
      awk '
        BEGIN { in_step=0; step_name=""; step_uses=""; cont_err=0; }
        /^[[:space:]]*-[[:space:]]/ {
          in_step=1
          step_name=""; step_uses=""; cont_err=0
          next
        }
        in_step && /[[:space:]]*name:[[:space:]]*/ {
          sub(/^[[:space:]]*name:[[:space:]]*/, "")
          sub(/[[:space:]]*#.*$/, "")
          step_name=$0
          if (cont_err && tolower(step_name) ~ /security/) { exit 1 }
          next
        }
        in_step && /[[:space:]]*uses:[[:space:]]*/ {
          sub(/^[[:space:]]*uses:[[:space:]]*/, "")
          sub(/[[:space:]]*#.*$/, "")
          step_uses=$0
          if (cont_err && (tolower(step_uses) ~ /security/)) { exit 1 }
          next
        }
        in_step && /[[:space:]]*continue-on-error:[[:space:]]*true/ {
          cont_err=1
          if (tolower(step_name) ~ /security/ || tolower(step_uses) ~ /security/) { exit 1 }
          next
        }
        /^[^[:space:]]/ && !/^[[:space:]]*-[[:space:]]/ { in_step=0 }
        END { exit 0 }
      ' "$f" || { found=1; break; }
    done < <(find .github/workflows -type f \( -name "*.yml" -o -name "*.yaml" \) 2>/dev/null)

    if [ "$found" -ne 0 ]; then
      exit 1
    else
      exit 0
    fi

