    in_step && /[[:space:]]*continue-on-error:[[:space:]]*true/ {
      cont_err=1
      if (tolower(step_name) ~ /security/ || tolower(step_uses) ~ /security/) { exit 1 }
      next
    }
    /^[^[:space:]]/ && !/^[[:space:]]*-[[:space:]]/ { in_step=0 }
    END { exit 0 }
  ' "$f" || { found=1; break; }
done < <(find .github/workflows -type f \( -name "*.yml" -o -name "*.yaml" \) 2>/dev/null)

